```javascript
let N;
const M = 305;
const INF = 1e9;

const possibleKnight = [
    { x: 2, y: 1 },
    { x: -2, y: 1 },
    { x: 2, y: -1 },
    { x: -2, y: -1 },
    { x: 1, y: 2 },
    { x: -1, y: 2 },
    { x: 1, y: -2 },
    { x: -1, y: -2 }
];

let dist = Array.from({ length: M }, () => Array.from({ length: M }, () => ({ x: INF, y: INF })));

function inBounds(p) {
    return 0 <= p.x && p.x < N && 0 <= p.y && p.y < N;
}

function hash(x, y, p) {
    return x * N * 3 + y * 3 + p;
}

function min(a, b) {
    if (a.x === b.x) {
        return a.y < b.y ? a : b;
    }
    return a.x < b.x ? a : b;
}

function sum(p1, p2) {
    return { x: p1.x + p2.x, y: p1.y + p2.y };
}

function solve(input) {
    const tokens = input.trim().split(/\s+/);
    let idx = 0;
    function nextInt() {
        return parseInt(tokens[idx++], 10);
    }

    N = nextInt();
    const pos = new Array(N * N);
    const A = Array.from({ length: N }, () => new Array(N));

    for (let x = 0; x < N; x++) {
        for (let y = 0; y < N; y++) {
            A[x][y] = nextInt() - 1;
            pos[A[x][y]] = { x, y };
        }
    }

    for (let i = 0; i < M; i++) {
        for (let j = 0; j < M; j++) {
            dist[i][j] = { x: INF, y: INF };
        }
    }
    for (let i = 0; i < M; i++) {
        dist[i][i] = { x: 0, y: 0 };
    }

    for (let x = 0; x < N; x++) {
        for (let y = 0; y < N; y++) {
            // knight
            for (let i = 0; i < possibleKnight.length; i++) {
                const nx = x + possibleKnight[i].x;
                const ny = y + possibleKnight[i].y;
                if (inBounds({ x: nx, y: ny })) {
                    dist[hash(x, y, 0)][hash(nx, ny, 0)] = { x: 1, y: 0 };
                }
            }
            // bishop
            for (let i = -N + 1; i <= N - 1; i++) {
                const nx = x + i;
                let ny = y + i;
                if (inBounds({ x: nx, y: ny })) {
                    dist[hash(x, y, 1)][hash(nx, ny, 1)] = { x: 1, y: 0 };
                }
                ny = y - i;
                if (inBounds({ x: nx, y: ny })) {
                    dist[hash(x, y, 1)][hash(nx, ny, 1)] = { x: 1, y: 0 };
                }
            }
            // rook
            for (let i = 0; i < N; i++) {
                let nx = i;
                let ny = y;
                dist[hash(x, y, 2)][hash(nx, ny, 2)] = { x: 1, y: 0 };
                nx = x;
                ny = i;
                dist[hash(x, y, 2)][hash(nx, ny, 2)] = { x: 1, y: 0 };
            }

            for (let i = 0; i < 3; i++) {
                for (let j = 0; j < 3; j++) {
                    if (i !== j) {
                        dist[hash(x, y, i)][hash(x, y, j)] = { x: 1, y: 1 };
                    }
                }
            }
        }
    }

    // Floyd-Warshall
    for (let k = 0; k < M; k++) {
        for (let i = 0; i < M; i++) {
            for (let j = 0; j < M; j++) {
                const via = sum(dist[i][k], dist[k][j]);
                dist[i][j] = min(dist[i][j], via);
            }
        }
    }

    const dp = Array.from({ length: N * N }, () => [
        { x: INF, y: INF },
        { x: INF, y: INF },
        { x: INF, y: INF }
    ]);

    dp[0][0] = { x: 0, y: 0 };
    dp[0][1] = { x: 0, y: 0 };
    dp[0][2] = { x: 0, y: 0 };

    for (let i = 0; i < N * N - 1; i++) {
        for (let j = 0; j < 3; j++) {
            for (let k = 0; k < 3; k++) {
                const d = dist[hash(pos[i].x, pos[i].y, j)][hash(pos[i + 1].x, pos[i + 1].y, k)];
                const candidate = sum(dp[i][j], d);
                dp[i + 1][k] = min(dp[i + 1][k], candidate);
            }
        }
    }

    let ans = { x: INF, y: INF };
    ans = min(ans, dp[N * N - 1][0]);
    ans = min(ans, dp[N * N - 1][1]);
    ans = min(ans, dp[N * N - 1][2]);

    console.log(`${ans.x} ${ans.y}`);
}

let input = '';
process.stdin.resume();
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => {
    input += chunk;
});
process.stdin.on('end', () => {
    solve(input);
});
