    Point.of(-2, 1),
    Point.of(2, -1),
    Point.of(-2, -1),
    Point.of(1, 2),
    Point.of(-1, 2),
    Point.of(1, -2),
    Point.of(-1, -2)
];

let dist = Array.from({ length: M }, () => Array(M).fill(null));

function inBounds(p) {
    return 0 <= p.x && p.x < N && 0 <= p.y && p.y < N;
}

function solve(input) {
    N = input.nextInt();
    const pos = new Array(N * N);
    const A = Array.from({ length: N }, () => new Array(N));

    for (let x = 0; x < N; x++) {
        for (let y = 0; y < N; y++) {
            A[x][y] = input.nextInt() - 1;
            pos[A[x][y]] = Point.of(x, y);
        }
    }

    for (let i = 0; i < M; i++) {
        for (let j = 0; j < M; j++) {
            dist[i][j] = Point.of(INF, INF);
        }
    }
    for (let i = 0; i < M; i++) {
        dist[i][i] = Point.of(0, 0);
    }

    for (let x = 0; x < N; x++) {
        for (let y = 0; y < N; y++) {
            // knight
            for (let i = 0; i < possibleKnight.length; i++) {
                const nx = x + possibleKnight[i].x;
                const ny = y + possibleKnight[i].y;
                if (inBounds(Point.of(nx, ny))) {
                    dist[Point.hash(x, y, 0)][Point.hash(nx, ny, 0)] = Point.of(1, 0);
                }
            }
            // bishop
            for (let i = -N + 1; i <= N - 1; i++) {
                const nx = x + i;
                let ny = y + i;
                if (inBounds(Point.of(nx, ny))) {
                    dist[Point.hash(x, y, 1)][Point.hash(nx, ny, 1)] = Point.of(1, 0);
                }

                ny = y - i;
                if (inBounds(Point.of(nx, ny))) {
                    dist[Point.hash(x, y, 1)][Point.hash(nx, ny, 1)] = Point.of(1, 0);
                }
            }

            // rook
            for (let i = 0; i < N; i++) {
                let nx = i;
                let ny = y;
                dist[Point.hash(x, y, 2)][Point.hash(nx, ny, 2)] = Point.of(1, 0);
                nx = x;
                ny = i;
                dist[Point.hash(x, y, 2)][Point.hash(nx, ny, 2)] = Point.of(1, 0);
            }

            for (let i = 0; i < 3; i++) {
                for (let j = 0; j < 3; j++) {
                    if (i !== j) {
                        dist[Point.hash(x, y, i)][Point.hash(x, y, j)] = Point.of(1, 1);
                    }
                }
            }
        }
    }

    for (let k = 0; k < M; k++) {
        for (let i = 0; i < M; i++) {
            for (let j = 0; j < M; j++) {
                dist[i][j] = Point.min(dist[i][j], Point.sum(dist[i][k], dist[k][j]));
            }
        }
    }

    const dp = Array.from({ length: N * N }, () => Array(3).fill(null));
    for (let i = 0; i < N * N; i++) {
        for (let j = 0; j < 3; j++) {
            dp[i][j] = Point.of(INF, INF);
        }
    }

    dp[0][0] = dp[0][1] = dp[0][2] = Point.of(0, 0);

    for (let i = 0; i < N * N - 1; i++) {
        for (let j = 0; j < 3; j++) {
            for (let k = 0; k < 3; k++) {
