        }
    }

    let ans = Point.of(INF, INF);
    ans = Point.min(ans, dp[N * N - 1][0]);
    ans = Point.min(ans, dp[N * N - 1][1]);
    ans = Point.min(ans, dp[N * N - 1][2]);

    console.log(ans.toString());
